// Parse the Ollama classification reply, sanitize it, attach to the
// original feedback row, and decide the routing action.
// Allowed classes (anything else falls back to 'question').
const ALLOWED = new Set(['bug','feature-request','process-improvement','priority-change','kudo','question','clinical-note']);

// strip <think>...</think> blocks (DeepSeek pattern), trim, lowercase, take first token
function sanitize(reply) {
  if (!reply) return 'question';
  let r = String(reply).replace(/<think>[\s\S]*?<\/think>/g, '').trim().toLowerCase();
  r = r.split(/[\s\n,.]/)[0];
  return ALLOWED.has(r) ? r : 'question';
}

const items = $input.all();
const out = items.map(it => {
  const j = it.json || {};
  const cls = sanitize(j.response);
  const orig = j.__orig || {}; // carries forward the feedback row
  // Domain-authority weight (Christina vs Darrell heuristic on display_name)
  const submitter = (orig.display_name || '').toLowerCase();
  let route_recipient = 'darrell';
  if (cls === 'question' || cls === 'clinical-note') {
    route_recipient = submitter.includes('christina') ? 'darrell' : 'christina';
  }
  return {
    json: {
      feedback_id: orig.id,
      submitter: orig.display_name,
      classification: cls,
      route_recipient,
      feedback_text: orig.feedback_text,
      original: orig,
    },
  };
});
return out;

// Build the markdown for docs/00-foundations/ai-suggestions/YYYY-MM-DD-HHmm.md
// In dry-run mode the path is .../ai-suggestions/dry-run/YYYY-MM-DD-HHmm.md
const now = new Date();
const pad = n => String(n).padStart(2, '0');
const stamp = `${now.getFullYear()}-${pad(now.getMonth()+1)}-${pad(now.getDate())}-${pad(now.getHours())}${pad(now.getMinutes())}`;

// pull dry_run flag from earlier node
const preflight = $items('Pre-flight: read settings + state')[0]?.json || {};
const dry = !!preflight.dry_run;

const projects = $input.all().map(i => i.json);
let body = `# AI suggestions — ${stamp}\n\n`;
if (dry) body += `> **DRY-RUN.** No mutations landed. This is the would-have-done report.\n\n`;

body += `## Per-project state\n\n`;
projects.slice(0, 12).forEach(p => {
  body += `### ${p.name}\n`;
  body += `Status: ${p.status} · Last activity: ${p.updated_at}\n\n`;
  const done = (p.done || []).map(d => `- ${d.title} (${d.at})`).join('\n') || '- (none in window)';
  const doing = (p.doing || []).map(d => `- ${d.title} (priority ${d.priority})`).join('\n') || '- (none pending)';
  body += `**Done (last 5 approved)**\n${done}\n\n`;
  body += `**Doing (top 3 pending)**\n${doing}\n\n`;
  body += `**Next for sustainability** *(would be Anthropic-generated when budget allows; placeholder for v0)*\n`;
  body += `- Consider one or two pieces of work that keep this project viable long-term.\n\n`;
});

const folder = dry ? 'docs/00-foundations/ai-suggestions/dry-run' : 'docs/00-foundations/ai-suggestions';
return [{ json: { path: `${folder}/${stamp}.md`, content: body, stamp, dry } }];
